CREATE TABLE IF NOT EXISTS schema_migrations (version integer PRIMARY KEY, applied_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS users (id text PRIMARY KEY, email text NOT NULL UNIQUE, name text NOT NULL, role text NOT NULL CHECK(role IN ('viewer','reviewer','admin','ingestion')), password_hash text NOT NULL);
CREATE TABLE IF NOT EXISTS sessions (token_hash text PRIMARY KEY, user_id text NOT NULL REFERENCES users(id), expires_at timestamptz NOT NULL);
CREATE TABLE IF NOT EXISTS customers (id text PRIMARY KEY, data jsonb NOT NULL);
CREATE TABLE IF NOT EXISTS addresses (id text PRIMARY KEY, customer_id text NOT NULL REFERENCES customers(id), data jsonb NOT NULL);
CREATE INDEX IF NOT EXISTS addresses_customer ON addresses(customer_id);
CREATE TABLE IF NOT EXISTS products (id text PRIMARY KEY, sku text NOT NULL UNIQUE, manufacturer_reference text, family text NOT NULL, description text NOT NULL, active boolean NOT NULL, data jsonb NOT NULL);
CREATE INDEX IF NOT EXISTS product_manufacturer ON products(manufacturer_reference);
CREATE INDEX IF NOT EXISTS product_family ON products(family);
CREATE INDEX IF NOT EXISTS product_search ON products USING gin(to_tsvector('simple', description));
CREATE TABLE IF NOT EXISTS customer_aliases (id text PRIMARY KEY, customer_id text NOT NULL REFERENCES customers(id), alias text NOT NULL, product_id text NOT NULL REFERENCES products(id), UNIQUE(customer_id,alias,product_id));
CREATE INDEX IF NOT EXISTS alias_scoped_lookup ON customer_aliases(customer_id,alias);
CREATE TABLE IF NOT EXISTS price_agreements (id text PRIMARY KEY, customer_id text NOT NULL REFERENCES customers(id), product_id text NOT NULL REFERENCES products(id), valid_from date NOT NULL, valid_to date, minimum_quantity numeric(20,6) NOT NULL, data jsonb NOT NULL);
CREATE INDEX IF NOT EXISTS prices_scoped_lookup ON price_agreements(customer_id,product_id,valid_from,valid_to,minimum_quantity);
CREATE TABLE IF NOT EXISTS stock_snapshots (product_id text PRIMARY KEY REFERENCES products(id), data jsonb NOT NULL);
CREATE TABLE IF NOT EXISTS synthetic_history (id text PRIMARY KEY, customer_id text NOT NULL REFERENCES customers(id), ordered_at date NOT NULL, data jsonb NOT NULL);
CREATE INDEX IF NOT EXISTS history_scoped ON synthetic_history(customer_id,ordered_at);
CREATE TABLE IF NOT EXISTS messages (id text PRIMARY KEY, transport_key text NOT NULL UNIQUE, content_hash text NOT NULL, data jsonb NOT NULL, intake jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
ALTER TABLE messages ADD COLUMN IF NOT EXISTS extracted jsonb;
CREATE INDEX IF NOT EXISTS messages_content_hash ON messages(content_hash);
CREATE INDEX IF NOT EXISTS messages_scoped_content ON messages(content_hash,(data->>'trustedCustomerId'));
CREATE INDEX IF NOT EXISTS product_attribute_filter ON products USING gin ((data->'attributes'));
CREATE TABLE IF NOT EXISTS documents (id text PRIMARY KEY, message_id text NOT NULL REFERENCES messages(id), data jsonb NOT NULL, storage_path text);
CREATE TABLE IF NOT EXISTS orders (id text PRIMARY KEY, message_id text NOT NULL UNIQUE REFERENCES messages(id), customer_id text REFERENCES customers(id), po_number text, status text NOT NULL, version integer NOT NULL, content_hash text NOT NULL, data jsonb NOT NULL, created_at timestamptz NOT NULL, updated_at timestamptz NOT NULL);
CREATE INDEX IF NOT EXISTS orders_queue ON orders(status,created_at DESC,id);
CREATE INDEX IF NOT EXISTS orders_business_duplicate ON orders(customer_id,po_number);
CREATE TABLE IF NOT EXISTS order_versions (order_id text NOT NULL REFERENCES orders(id), version integer NOT NULL, content_hash text NOT NULL, data jsonb NOT NULL, PRIMARY KEY(order_id,version));
CREATE TABLE IF NOT EXISTS approvals (id text PRIMARY KEY, order_id text NOT NULL REFERENCES orders(id), version integer NOT NULL, content_hash text NOT NULL, data jsonb NOT NULL, UNIQUE(order_id,version));
CREATE TABLE IF NOT EXISTS exports (id text PRIMARY KEY, order_id text NOT NULL REFERENCES orders(id), version integer NOT NULL, idempotency_key text NOT NULL UNIQUE, data jsonb NOT NULL, artifact bytea NOT NULL, UNIQUE(order_id,version));
CREATE TABLE IF NOT EXISTS jobs (id text PRIMARY KEY, type text NOT NULL, message_id text REFERENCES messages(id), order_id text REFERENCES orders(id), status text NOT NULL, attempts integer NOT NULL DEFAULT 0, max_attempts integer NOT NULL DEFAULT 3, available_at timestamptz NOT NULL DEFAULT now(), lease_owner text, lease_expires_at timestamptz, error_code text, error_message text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS jobs_claim ON jobs(status,available_at,lease_expires_at);
CREATE TABLE IF NOT EXISTS audit_events (id text PRIMARY KEY, order_id text REFERENCES orders(id), data jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS audit_order ON audit_events(order_id,created_at);
CREATE TABLE IF NOT EXISTS evidence (id text PRIMARY KEY, message_id text NOT NULL REFERENCES messages(id), data jsonb NOT NULL);
CREATE TABLE IF NOT EXISTS model_usage (id text PRIMARY KEY, order_id text REFERENCES orders(id), run_id text NOT NULL, data jsonb NOT NULL);
CREATE TABLE IF NOT EXISTS budget_runs (id text PRIMARY KEY, cap_usd numeric(20,6) NOT NULL CHECK(cap_usd>=0), spent_usd numeric(20,6) NOT NULL DEFAULT 0, reserved_usd numeric(20,6) NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS budget_reservations (id text PRIMARY KEY, run_id text NOT NULL REFERENCES budget_runs(id), order_id text NOT NULL, amount_usd numeric(20,6) NOT NULL, actual_usd numeric(20,6), state text NOT NULL CHECK(state IN ('reserved','settled')), created_at timestamptz NOT NULL DEFAULT now());
INSERT INTO schema_migrations(version) VALUES(1) ON CONFLICT DO NOTHING;
